// Health state values reported by Status (architecture §2.2.2 HealthResponse,
// §7.3). DEGRADED is reserved for a non-blocking warning; the Manager tracks
// serving / not_serving / failed from the substrate + restart state in MVP.
const (
	stateServing    = "serving"
	stateDegraded   = "degraded"
	stateNotServing = "not_serving"
	stateFailed     = "failed"
)

// Restart / launch timing constants (architecture §7.3, §7.4).
const (
	// goPluginProtocolVersion is the go-plugin wire protocol version; it must
	// match pkg/sdk's server-side value (go-plugin CoreProtocolVersion == 1).
	goPluginProtocolVersion = 1
	// scannerPluginKey is the client PluginSet dispense key. The client and
	// server PluginSet keys are independent — the gRPC service is bound by its
	// fully-qualified name — so this key only needs to exist in the client map.
	scannerPluginKey = "scanner"
	// metadataSourcePluginKey is the client PluginSet dispense key for the
	// metadata_source capability. Same key-independence as scannerPluginKey —
	// it is a local dispense handle, NOT the gRPC service binding.
	metadataSourcePluginKey = "metadata_source"
	// maxRestarts is the consecutive-failed-restart ceiling (§7.3: three).
	maxRestarts = 3
	// shutdownGrace bounds the Shutdown RPC + SIGTERM grace window (§7.4: 10s).
	shutdownGrace = 10 * time.Second
	// handshakeTimeout bounds the domain Plugin.Handshake RPC on Start.
	handshakeTimeout = 15 * time.Second
	// defaultPollInterval is how often the per-plugin monitor checks for an
	// unexpected subprocess exit. §7.3's 30s cadence is the domain Health RPC
	// poll; exit detection is independent and tighter. Tests override this.
	defaultPollInterval = time.Second
	// backoffInitial / backoffFactor / backoffCap define the §7.3 restart
	// backoff curve (1s -> 2x -> cap 60s, jittered).
	backoffInitial = 1 * time.Second
	backoffFactor  = 2
	backoffCap     = 60 * time.Second
)

// Deps is the configuration a Manager is opened against: the magic-cookie pair
// the core shares with every plugin (architecture §2.2.1) and the core version
// advertised in the domain Handshake (§2.2.2 min_core_version).
type Deps struct {
	MagicCookieKey   string
	MagicCookieValue string
	CoreVersion      string
}

// Health is a plugin's current state plus its restart bookkeeping. State is one
// of the state* constants (serving | degraded | not_serving | failed).
type Health struct {
	State         string
	Message       string
	Restarts      int
	LastCheckedAt time.Time
}

