// Load registers a plugin binary and the capabilities it declares, WITHOUT
// launching a subprocess (dev mode: binaryPath is a filesystem path). A plugin
// may be loaded at most once; re-Loading the same id is an error. The
// capabilities are used to validate Scanner requests against the declared
// (type, id) slots.
func (m *Manager) Load(pluginID, binaryPath string, caps []sdk.Capability) error {
	if pluginID == "" {
		return errors.New("plugin: load: empty plugin id")
	}
	if binaryPath == "" {
		return fmt.Errorf("plugin: load %q: empty binary path", pluginID)
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if _, ok := m.plugins[pluginID]; ok {
		return fmt.Errorf("plugin: load %q: already loaded", pluginID)
	}
	m.plugins[pluginID] = &pluginEntry{
		binaryPath:  binaryPath,
		caps:        caps,
		state:       stateNotServing,
		lastChecked: m.now(),
	}
	return nil
}

// Scanner returns the typed sdk.Scanner client for a plugin's declared scanner
// capability, wrapping the live gRPC connection to the subprocess. It is the
// module map's generic "Call" realized without reflect (INV1). It errors if the
// plugin is not loaded, not serving, has no live connection, or did not declare
// the requested scanner capability.
func (m *Manager) Scanner(pluginID, capabilityID string) (sdk.Scanner, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	e, ok := m.plugins[pluginID]
	if !ok {
		return nil, fmt.Errorf("plugin: scanner: %q not loaded", pluginID)
	}
	if e.state != stateServing {
		return nil, fmt.Errorf("plugin: scanner: %q not serving (state=%s)", pluginID, e.state)
	}
	if e.rp == nil {
		return nil, fmt.Errorf("plugin: scanner: %q has no live connection", pluginID)
	}
	if !hasScannerCapability(e.caps, capabilityID) {
		return nil, fmt.Errorf("plugin: scanner: capability %q not declared by %q", capabilityID, pluginID)
	}
	return e.rp.scanner, nil
}

// hasScannerCapability reports whether caps declares a scanner slot with the
// given instance id.
func hasScannerCapability(caps []sdk.Capability, capabilityID string) bool {
	for _, c := range caps {
		if c.Type == "scanner" && c.ID == capabilityID {
			return true
		}
	}
	return false
}

